import 'server-only'
import type { SupabaseClient } from '@supabase/supabase-js'

/**
 * Invite codes are generated by `app/api/admin/invite-codes` as `STAFF-XXXX-XXXX` / `ADMIN-XXXX-XXXX`
 * from an uppercase alphanumeric alphabet. Anything outside that shape is rejected before it reaches
 * the database, so SQL/PostgREST pattern characters (`%`, `_`, `*`, `,`, `.`) can never be used as wildcards.
 */
const INVITE_CODE_PATTERN = /^[A-Z0-9]+(?:-[A-Z0-9]+)*$/

export function normalizeInviteCode(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null
  const code = raw.trim().toUpperCase().replace(/\s+/g, '-')
  if (code.length < 4 || code.length > 64) return null
  return INVITE_CODE_PATTERN.test(code) ? code : null
}

export type InviteRecord = {
  id: string
  role: 'staff' | 'admin'
  recipient_email: string | null
  expires_at: string
  is_used: boolean
}

export type InviteCheck =
  { ok: true; invite: InviteRecord } | { ok: false; reason: 'not_found' | 'used' | 'expired' | 'email_mismatch' }

/**
 * Read-only pre-check used to give users a helpful message before any account change.
 * Consumption must still go through the atomic `redeem_invite_code` RPC.
 */
export async function checkInviteCode(
  adminClient: SupabaseClient,
  code: string,
  email?: string | null,
): Promise<InviteCheck> {
  const { data: invite, error } = await adminClient
    .from('invite_codes')
    .select('id, role, recipient_email, expires_at, is_used')
    .eq('code', code)
    .maybeSingle()

  if (error || !invite) return { ok: false, reason: 'not_found' }
  if (invite.is_used) return { ok: false, reason: 'used' }
  if (new Date(invite.expires_at).getTime() < Date.now()) return { ok: false, reason: 'expired' }
  if (email && invite.recipient_email && invite.recipient_email.toLowerCase().trim() !== email.toLowerCase().trim()) {
    return { ok: false, reason: 'email_mismatch' }
  }
  return { ok: true, invite: invite as InviteRecord }
}

export const inviteErrorMessages: Record<Exclude<InviteCheck, { ok: true }>['reason'], string> = {
  not_found: 'Invalid invite code. Please check the code or leave it blank to request access.',
  used: 'This invite code has already been redeemed. Please request a new code.',
  expired: 'This invite code has expired. Please ask your administrator to generate a new code.',
  // Deliberately does not echo the reserved address back to the caller.
  email_mismatch: 'This invite code is reserved for a different email address.',
}

/**
 * Atomically consumes the invite and assigns the profile role (see migration
 * 20261117100000_security_phase0_hardening). Service role only.
 */
export async function redeemInviteForUser(
  adminClient: SupabaseClient,
  code: string,
  userId: string,
  email: string,
): Promise<{ ok: true; role: 'staff' | 'admin' } | { ok: false; message: string }> {
  const { data, error } = await adminClient.rpc('redeem_invite_code', {
    p_code: code,
    p_user_id: userId,
    p_email: email,
  })
  if (error) {
    if (error.code === 'P0002') return { ok: false, message: inviteErrorMessages.not_found }
    if (error.code === '22023') return { ok: false, message: error.message }
    throw error
  }
  if (data !== 'staff' && data !== 'admin') {
    throw new Error('redeem_invite_code returned an unexpected role')
  }
  return { ok: true, role: data }
}
